<?php
namespace App\Livewire\Storefront;
use App\Models\CartItem; use App\Models\Transaction; use Illuminate\Support\Facades\DB; use Livewire\Attributes\Layout; use Livewire\Component;
#[Layout('layouts.store')]
class Checkout extends Component { public string $visitor_name=''; public string $visit_date=''; public string $notes=''; public function mount(){ $this->visitor_name=auth()->user()->name; $this->visit_date=now()->addDay()->toDateString(); } public function placeOrder(){ $data=$this->validate(['visitor_name'=>'required|string|max:100','visit_date'=>'required|date|after_or_equal:today','notes'=>'nullable|string|max:1000']); $items=CartItem::where('user_id',auth()->id())->with('product')->get(); if($items->isEmpty()){session()->flash('error','Keranjang masih kosong.');return $this->redirectRoute('cart');} $order=DB::transaction(function()use($data,$items){$total=$items->sum(fn($i)=>$i->product->price*$i->quantity);$order=Transaction::create($data+['user_id'=>auth()->id(),'transaction_code'=>'JLT-'.now()->format('Ymd').'-'.str_pad((string)(Transaction::count()+1),4,'0',STR_PAD_LEFT),'total_price'=>$total,'status'=>'pending']);foreach($items as $item)$order->items()->create(['product_id'=>$item->product_id,'quantity'=>$item->quantity,'price'=>$item->product->price,'subtotal'=>$item->product->price*$item->quantity]);CartItem::where('user_id',auth()->id())->delete();return $order;}); session()->flash('success',"Pemesanan {$order->transaction_code} berhasil dibuat. Berikut rincian pesanan Anda."); return $this->redirectRoute('orders.show', ['transaction' => $order->id]); } public function render(){return view('livewire.storefront.checkout',['items'=>CartItem::where('user_id',auth()->id())->with('product')->get()]);} }
